replacements.search:
after.src = img(e.after);
before.src = img(e.before);
bg.src = img(e.after);

replacements.replacement:
after.src = img(e.after);
after.alt = `After – ${e.mode}: ${e.prompt}`;
before.src = img(e.before);
before.alt = `Before – ${e.mode}: ${e.prompt}`;
bg.src = img(e.after);

cmp.addEventListener("pointercancel", () => (dragging = false));
cmp.addEventListener("keydown", (ev) => {
  const keys = ["ArrowLeft", "ArrowRight", "Home", "End"];
  if (!keys.includes(ev.key)) return;
  ev.preventDefault();
  cancelAnimationFrame(raf);
  const current_split = parseFloat(cmp.getAttribute("aria-valuenow") ?? "50") || 50;
  let next = current_split;
  if (ev.key === "ArrowLeft") next = current_split - 5;
  else if (ev.key === "ArrowRight") next = current_split + 5;
  else if (ev.key === "Home") next = 0;
  else if (ev.key === "End") next = 100;
  setSplit(next);
});
